actions.customAction:
var webhookUrl =
  "https://tsc-wfl.m-wiesner.de/webhook/mgvo-gruppen";

console.log("=== MGVO Gruppenladen gestartet ===");
console.log("Webhook:", webhookUrl);

instance.gruppenLadevorgangGestartet = true;

fetch('/webhook/me', { credentials: 'include', cache: 'no-store' })
.then(function (antwort) {
  if (!antwort.ok) {
    throw new Error('Memberdaten konnten nicht geladen werden: HTTP ' + antwort.status);
  }
  return antwort.json();
})
.then(function (response) {
  var daten = Array.isArray(response) ? response[0] : response;
  if (!daten || !(daten.gefunden === true || daten.erfolgreich === true) || !daten.person) {
    throw new Error('Keine gültigen Memberdaten vorhanden.');
  }

  var person = daten.person;
  if (typeof person.gruppenliste !== 'string') {
    throw new Error('Die Memberdaten enthalten keine gültige gruppenliste.');
  }

  // IDs als Strings erhalten, einschließlich führender Nullen.
  instance.eigeneGruppenIds = new Set(
    person.gruppenliste.split(',').map(function (id) {
      return id.trim();
    }).filter(Boolean)
  );

  // Der allgemeine Katalog benötigt keine Anmelde-Cookies.
  return fetch(webhookUrl, { credentials: 'omit', cache: 'no-store' });
})
.then(function (antwort) {

  console.log("HTTP-Status:", antwort.status);
  console.log("HTTP ok:", antwort.ok);

  if (!antwort.ok) {
    throw new Error(
      "Der Server antwortete mit Status " +
      antwort.status +
      "."
    );
  }

  return antwort.json();
})
.then(function (mgvoDaten) {

  console.log("=== Rohdaten vom Webhook ===");
  console.log(mgvoDaten);

  /*
   * Erwartetes Format:
   *
   * {
   *   gruppen: [...]
   * }
   */
  if (
    !mgvoDaten ||
    !Array.isArray(mgvoDaten.gruppen)
  ) {

    console.error(
      "Ungültige MGVO-Antwort:",
      mgvoDaten
    );

    throw new Error(
      "Die Antwort enthält keine gültige Gruppenliste."
    );
  }

  var gruppenListe =
    mgvoDaten.gruppen;

  console.log(
    "Anzahl Gruppen vom Webhook:",
    gruppenListe.length
  );

  console.table(
    gruppenListe.map(function (gruppe) {
      return {
        gruid: gruppe.gruid,
        grubez: gruppe.grubez,
        inaktiv: gruppe.inaktiv,
        anzahlTrainingszeiten:
          Array.isArray(gruppe.gruzar)
            ? gruppe.gruzar.length
            : 0
      };
    })
  );

  var wochentage = {
    "1": "Montag",
    "2": "Dienstag",
    "3": "Mittwoch",
    "4": "Donnerstag",
    "5": "Freitag",
    "6": "Samstag",
    "7": "Sonntag"
  };

  var zeilenMitSortierung = [];

  gruppenListe.forEach(function (
    gruppe,
    gruppenIndex
  ) {

    console.log(
      "Verarbeite Gruppe:",
      gruppenIndex + 1,
      gruppe.gruid,
      gruppe.grubez,
      "inaktiv:",
      gruppe.inaktiv
    );

    /*
     * Inaktive Gruppen überspringen
     */
    if (gruppe.inaktiv === true) {

      console.log(
        "Gruppe übersprungen, da inaktiv:",
        gruppe.gruid
      );

      return;
    }

    var gruppenId =
      String(
        gruppe.gruid || ""
      ).trim();

    if (!gruppenId) {

      console.warn(
        "Gruppe ohne gruid übersprungen:",
        gruppe
      );

      return;
    }

    var kategorie =
      String(
        gruppe.hp_kat ||
        gruppe.grukat ||
        ""
      ).trim();

    var gruppenname =
      String(
        gruppe.grubez || ""
      );

    /*
     * ID am Anfang entfernen
     */
    gruppenname =
      gruppenname.replace(
        /^\s*\d+\s*_\s*/,
        ""
      );

    /*
     * Inhalt in [] am Ende entfernen
     */
    gruppenname =
      gruppenname.replace(
        /\s*\[[^\]]*\]\s*$/,
        ""
      );

    gruppenname =
      gruppenname.trim();

    var trainingszeiten =
      gruppe.gruzar;

    /*
     * Auch Gruppen ohne Trainingszeit anzeigen
     */
    if (
      !Array.isArray(trainingszeiten) ||
      trainingszeiten.length === 0
    ) {
      trainingszeiten = [{}];
    }

    trainingszeiten.forEach(
      function (trainingszeit) {

        var wochentagNummer =
          Number(
            trainingszeit.wotag
          );

        if (
          !Number.isInteger(
            wochentagNummer
          ) ||
          wochentagNummer < 1 ||
          wochentagNummer > 7
        ) {
          wochentagNummer = 99;
        }

        var startzeit =
          String(
            trainingszeit.startzeit ||
            ""
          ).substring(0, 5);

        var endzeit =
          String(
            trainingszeit.endzeit ||
            ""
          ).substring(0, 5);

        var termin = "";
        var trainer = "";

        if (
          wochentage[
            trainingszeit.wotag
          ]
        ) {
          termin =
            wochentage[
              trainingszeit.wotag
            ];
        }

        if (
          startzeit &&
          endzeit
        ) {

          if (termin) {
            termin += ", ";
          }

          termin +=
            startzeit +
            "–" +
            endzeit +
            " Uhr";

        } else if (startzeit) {

          if (termin) {
            termin += ", ";
          }

          termin +=
            startzeit +
            " Uhr";
        }

        /*
         * Trainer bestimmen
         */
        if (
          trainingszeit.trname
        ) {

          trainer =
            String(
              trainingszeit.trname
            ).trim();

        } else if (
          gruppe.trnameall
        ) {

          trainer =
            String(
              gruppe.trnameall
            ).trim();
        }

        var anzeigeBestandteile = [];

        if (gruppenname) {
          anzeigeBestandteile.push(
            gruppenname
          );
        }

        if (termin) {
          anzeigeBestandteile.push(
            termin
          );
        }

        if (trainer) {
          anzeigeBestandteile.push(
            trainer
          );
        }

        var erzeugteZeile = {
          angemeldet: instance.eigeneGruppenIds.has(gruppenId),

          gruppenid:
            gruppenId,

          gruppe:
            anzeigeBestandteile.join(
              " | "
            ),

          sortierKategorie:
            kategorie,

          sortierWochentag:
            wochentagNummer,

          sortierStartzeit:
            startzeit || "99:99"
        };

        console.log(
          "Erzeugte Tabellenzeile:",
          erzeugteZeile
        );

        zeilenMitSortierung.push(
          erzeugteZeile
        );
      }
    );
  });

  console.log(
    "Anzahl erzeugter Zeilen vor Sortierung:",
    zeilenMitSortierung.length
  );

  console.table(
    zeilenMitSortierung
  );

  /*
   * Sortierung
   */
  zeilenMitSortierung.sort(
    function (
      ersteZeile,
      zweiteZeile
    ) {

      var kategorieVergleich =
        ersteZeile.sortierKategorie
          .localeCompare(
            zweiteZeile.sortierKategorie,
            "de",
            {
              sensitivity: "base",
              numeric: true
            }
          );

      if (
        kategorieVergleich !== 0
      ) {
        return kategorieVergleich;
      }

      if (
        ersteZeile.sortierWochentag !==
        zweiteZeile.sortierWochentag
      ) {
        return (
          ersteZeile.sortierWochentag -
          zweiteZeile.sortierWochentag
        );
      }

      var startzeitVergleich =
        ersteZeile.sortierStartzeit
          .localeCompare(
            zweiteZeile.sortierStartzeit,
            "de",
            {
              numeric: true
            }
          );

      if (
        startzeitVergleich !== 0
      ) {
        return startzeitVergleich;
      }

      return ersteZeile.gruppe
        .localeCompare(
          zweiteZeile.gruppe,
          "de",
          {
            sensitivity: "base",
            numeric: true
          }
        );
    }
  );

  console.log(
    "=== Nach Sortierung ==="
  );

  console.table(
    zeilenMitSortierung
  );

  /*
   * Daten für Form.io Data Grid
   */
  // Eine Zeile pro Gruppe; mehrere Trainingszeiten zusammenfassen.
  var nachId = new Map();
  zeilenMitSortierung.forEach(function (zeile) {
    if (!nachId.has(zeile.gruppenid)) {
      nachId.set(zeile.gruppenid, {
        gruppenid: zeile.gruppenid,
        gruppe: zeile.gruppe,
        angemeldet: zeile.angemeldet,
        aenderung: ""
      });
    } else {
      var vorhanden = nachId.get(zeile.gruppenid);
      if (!vorhanden.gruppe.split("\n").includes(zeile.gruppe)) {
        vorhanden.gruppe += "\n" + zeile.gruppe;
      }
      if (vorhanden.angemeldet !== zeile.angemeldet) {
        vorhanden.angemeldet = null;
      }
    }
  });
  var tabellenZeilen = Array.from(nachId.values());

  console.log(
    "=== Daten für Form.io Data Grid ==="
  );

  console.table(
    tabellenZeilen
  );

  console.log(
    "Anzahl Data-Grid-Zeilen:",
    tabellenZeilen.length
  );

  /*
   * Data Grid befüllen
   */
  instance.setValue(
    tabellenZeilen
  );

  console.log(
    "instance.setValue() ausgeführt"
  );

  console.log(
    "instance.dataValue:",
    instance.dataValue
  );

  console.log(
    "data.gruppenTabelle:",
    data.gruppenTabelle
  );

  console.log(
    "=== MGVO Gruppenladen abgeschlossen ==="
  );
})
.catch(function (fehler) {

  // Kein automatischer Wiederholungsaufruf durch die Formularlogik.
  // Für einen neuen Versuch das Formular erneut öffnen.

  console.error(
    "=== Fehler beim Laden der MGVO-Gruppen ==="
  );

  console.error(
    fehler
  );


});

